-- SQL Quest practice dataset "school": Maple High School
-- Generated by scripts/gen-datasets.mjs (deterministic) - edit the generator, not this file.

CREATE TABLE teachers (
    teacher_id integer PRIMARY KEY,
    full_name  text NOT NULL,
    subject    text NOT NULL,
    hire_date  date NOT NULL,
    salary     numeric(9,2) NOT NULL
);

CREATE TABLE students (
    student_id  integer PRIMARY KEY,
    first_name  text NOT NULL,
    last_name   text NOT NULL,
    grade_level integer NOT NULL CHECK (grade_level BETWEEN 9 AND 12),
    birth_date  date NOT NULL,
    email       text,
    enrolled_on date NOT NULL
);

CREATE TABLE courses (
    course_id  integer PRIMARY KEY,
    title      text NOT NULL,
    subject    text NOT NULL,
    teacher_id integer REFERENCES teachers (teacher_id),
    credits    integer NOT NULL,
    room       text NOT NULL
);

CREATE TABLE enrollments (
    student_id  integer NOT NULL REFERENCES students (student_id),
    course_id   integer NOT NULL REFERENCES courses (course_id),
    term        text NOT NULL,
    final_score numeric(5,2),
    PRIMARY KEY (student_id, course_id, term)
);

CREATE TABLE exam_scores (
    exam_id    integer PRIMARY KEY,
    student_id integer NOT NULL REFERENCES students (student_id),
    course_id  integer NOT NULL REFERENCES courses (course_id),
    exam_date  date NOT NULL,
    exam_type  text NOT NULL,
    score      numeric(5,2) NOT NULL
);

CREATE TABLE clubs (
    club_id    integer PRIMARY KEY,
    name       text NOT NULL,
    advisor_id integer REFERENCES teachers (teacher_id)
);

CREATE TABLE club_members (
    club_id    integer NOT NULL REFERENCES clubs (club_id),
    student_id integer NOT NULL REFERENCES students (student_id),
    joined_on  date NOT NULL,
    PRIMARY KEY (club_id, student_id)
);












ANALYZE;
